    out.append('" style="width: 40px;">\n                                                </td>\n                                                <td style="width: 80px;">&nbsp;</td>\n                                                <td\n                                                    style="border-bottom:1px dashed #0327A7; width: 20%; font-size: 13px; line-height: 14px; color: #0b2840; text-align: center;">\n                                                    <img src="')
    out.append(to_str(f_base_url('assets/signature/HOD_SIGNATURE/Adobe_Scan.png')))
    out.append('" style="width: 123px;"></td>\n                                                <td style="width: 80px;">&nbsp;</td>\n                                                ')
    if T(ne(v_teacherSignature, '')):
        out.append('                                                ')
        v_path = cat(cat(FCPATH, 'assets/signature/teacher/'), f_basename(v_teacherSignature))
