        v_base64 = cat(cat(cat('data:image/', v_type), ';base64,'), f_base64_encode(v_data))
        out.append('                                                <td style="border-bottom:1px dashed #0327A7; width: 20%; font-size: 13px; line-height: 14px; color: #0b2840; text-align: center;">\n                                                    <img src="')
